  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 4
  if (argc == 1) {
    if ( extends(argtypes[1], '_p_std__vectorT_detector__Detection_t') && length(argv[[1]]) == 1 ) {
      f <- yolact__FastNms__SWIG_3;
    }
  } else if (argc == 2) {
    if (( extends(argtypes[1], '_p_std__vectorT_detector__Detection_t') && length(argv[[1]]) == 1 ) && ( is.numeric(argv[[2]]) && length(argv[[2]]) == 1 )) {
      f <- yolact__FastNms__SWIG_2;
    }
  } else if (argc == 3) {
    if (( extends(argtypes[1], '_p_std__vectorT_detector__Detection_t') && length(argv[[1]]) == 1 ) && ( is.numeric(argv[[2]]) && length(argv[[2]]) == 1 ) && ( (is.integer(argv[[3]]) || is.numeric(argv[[3]])) && length(argv[[3]]) == 1 )) {
      f <- yolact__FastNms__SWIG_1;
    }
  } else if (argc == 4) {
    if (( extends(argtypes[1], '_p_std__vectorT_detector__Detection_t') && length(argv[[1]]) == 1 ) && ( is.numeric(argv[[2]]) && length(argv[[2]]) == 1 ) && ( (is.integer(argv[[3]]) || is.numeric(argv[[3]])) && length(argv[[3]]) == 1 ) && ( (is.integer(argv[[4]]) || is.numeric(argv[[4]])) && length(argv[[4]]) == 1 )) {
      f <- yolact__FastNms__SWIG_0;
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for yolact__FastNms with argtypes (",toString(argtypes),")");
  };
  f(...);
